// Package docsgen renders the reference pages of the documentation site from
// the code itself, so they can never drift: the CLI tree, every environment
// variable in .env.example, the permission catalog and the Make targets.
// `ims gen docs` writes them under docs/reference; `--check` fails CI when a
// committed page is stale.
package docsgen

import (
	"bufio"
	"bytes"
	"fmt"
	"regexp"
	"sort"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"

	"github.com/Innovix-Matrix-Systems/ims-go-admin-starter/internal/authz"
)

// Page is one generated file, relative to the repository root.
type Page struct {
	Path    string
	Content []byte
}

// Inputs are the sources the pages are rendered from.
type Inputs struct {
	Root       *cobra.Command
	EnvExample []byte
	Makefile   []byte
}

// Render returns every generated reference page.
func Render(in Inputs) []Page {
	return []Page{
		{Path: "docs/reference/cli.md", Content: []byte(CLI(in.Root))},
		{Path: "docs/reference/configuration.md", Content: []byte(Configuration(in.EnvExample))},
		{Path: "docs/reference/permissions.md", Content: []byte(Permissions())},
		{Path: "docs/reference/make.md", Content: []byte(Make(in.Makefile))},
	}
}

func header(title, description, source string) string {
	// editUrl: false hides the site's "Edit page" link: edits belong in the source.
	return fmt.Sprintf("---\ntitle: %s\ndescription: %s\neditUrl: false\n---\n\n"+
		"<!-- Generated by `ims gen docs` from %s. Do not edit: run `make docs-gen`. -->\n\n",
		title, description, source)
}

// cell makes text safe inside a Markdown table cell.
func cell(text string) string {
	text = strings.ReplaceAll(strings.TrimSpace(text), "|", `\|`)
	return strings.ReplaceAll(text, "\n", " ")
}

// ── CLI ──────────────────────────────────────────────────────────────────

// CLI renders every command of the ims binary with its flags.
func CLI(root *cobra.Command) string {
	var b strings.Builder
	b.WriteString(header("CLI reference", "Every ims command and flag, generated from the Cobra command tree.",
		"the Cobra command tree (internal/cli)"))
	b.WriteString("The binary is the CLI. In development run commands from source with `go run ./cmd/app <command>`;\n" +
		"a built binary runs them as `ims <command>`. Global flags work with every command.\n" +
		"To add your own command, see [CLI commands](../guides/cli-commands.md).\n\n")

	b.WriteString("## Global flags\n\n")
	writeFlags(&b, root.PersistentFlags())

	commands := flatten(root)
	b.WriteString("## Commands\n\n| Command | Description |\n| --- | --- |\n")
	for _, cmd := range commands {
		fmt.Fprintf(&b, "| [`%s`](#%s) | %s |\n", path(cmd), anchor(path(cmd)), cell(cmd.Short))
	}
	b.WriteString("\n")

	for _, cmd := range commands {
		fmt.Fprintf(&b, "### %s\n\n", path(cmd))
		if long := strings.TrimSpace(cmd.Long); long != "" {
			b.WriteString(long + "\n\n")
		} else if cmd.Short != "" {
			b.WriteString(strings.TrimSpace(cmd.Short) + ".\n\n")
		}
		fmt.Fprintf(&b, "```bash\n%s\n```\n\n", strings.TrimSpace(cmd.UseLine()))
		if cmd.Example != "" {
			fmt.Fprintf(&b, "Examples:\n\n```bash\n%s\n```\n\n", trimExample(cmd.Example))
		}
		if cmd.HasAvailableLocalFlags() {
			writeFlags(&b, cmd.LocalNonPersistentFlags())
		}
	}
	return b.String()
}

func flatten(root *cobra.Command) []*cobra.Command {
	var out []*cobra.Command
	var walk func(*cobra.Command)
	walk = func(cmd *cobra.Command) {
		for _, child := range cmd.Commands() {
			if !child.IsAvailableCommand() || child.Name() == "help" || child.Name() == "completion" {
				continue
			}
			if child.Runnable() {
				out = append(out, child)
			}
			walk(child)
		}
	}
	walk(root)
	sort.Slice(out, func(i, j int) bool { return path(out[i]) < path(out[j]) })
	return out
}

func path(cmd *cobra.Command) string {
	return strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" ")
}

var nonAnchor = regexp.MustCompile(`[^a-z0-9 -]`)

// anchor mirrors the heading slugs the site generates (github-slugger).
func anchor(heading string) string {
	return strings.ReplaceAll(nonAnchor.ReplaceAllString(strings.ToLower(heading), ""), " ", "-")
}

func trimExample(example string) string {
	lines := strings.Split(strings.Trim(example, "\n"), "\n")
	for i, line := range lines {
		lines[i] = strings.TrimPrefix(line, "  ")
	}
	return strings.Join(lines, "\n")
}

func writeFlags(b *strings.Builder, flags *pflag.FlagSet) {
	var rows []string
	flags.VisitAll(func(flag *pflag.Flag) {
		if flag.Hidden || flag.Name == "help" {
			return
		}
		name := "`--" + flag.Name + "`"
		if flag.Shorthand != "" {
			name = "`-" + flag.Shorthand + "`, " + name
		}
		def := flag.DefValue
		if def == "" || def == "[]" || (flag.Value.Type() == "bool" && def == "false") {
			def = "—"
		} else {
			def = "`" + def + "`"
		}
		rows = append(rows, fmt.Sprintf("| %s | %s | %s |", name, def, cell(flag.Usage)))
	})
	if len(rows) == 0 {
		return
	}
	b.WriteString("| Flag | Default | Description |\n| --- | --- | --- |\n")
	b.WriteString(strings.Join(rows, "\n"))
	b.WriteString("\n\n")
}

// ── Configuration ────────────────────────────────────────────────────────

var (
	sectionLine = regexp.MustCompile(`^#\s*──\s*(.+?)\s*─*\s*$`)
	varLine     = regexp.MustCompile(`^(#\s*)?([A-Z][A-Z0-9_]*)=(.*)$`)
)

type envVar struct {
	name, value, note string
	optional          bool
}

type envSection struct {
	title string
	vars  []envVar
}

// Configuration renders every variable documented in .env.example.
func Configuration(envExample []byte) string {
	var sections []*envSection
	current := &envSection{title: "General"}
	var pending []string
	scanner := bufio.NewScanner(bytes.NewReader(envExample))
	for scanner.Scan() {
		line := strings.TrimRight(scanner.Text(), " \t")
		switch {
		case line == "":
			pending = nil
		case sectionLine.MatchString(line):
			current = &envSection{title: sectionLine.FindStringSubmatch(line)[1]}
			sections = append(sections, current)
			pending = nil
		case varLine.MatchString(line):
			m := varLine.FindStringSubmatch(line)
			value, note := splitComment(m[3])
			if len(pending) > 0 {
				note = strings.TrimSpace(strings.Join(pending, " ") + " " + note)
			}
			current.vars = append(current.vars, envVar{name: m[2], value: value, note: note, optional: m[1] != ""})
			pending = nil
		case strings.HasPrefix(line, "#"):
			text := strings.TrimSpace(strings.TrimPrefix(line, "#"))
			if text != "" {
				pending = append(pending, text)
			}
		}
	}
	if len(sections) == 0 {
		sections = []*envSection{current}
	}

	var b strings.Builder
	b.WriteString(header("Configuration reference", "Every environment variable the API reads, generated from .env.example.", ".env.example"))
	b.WriteString("Every setting lives in the environment. Copy `.env.example` to `.env` for local development; in\n" +
		"production systemd supplies an `EnvironmentFile`. Process environment always wins over `.env`\n" +
		"(precedence: `--env-file` → `APP_ENV_FILE` → `.env` → code defaults). `ims config:show` prints the\n" +
		"effective values with secrets masked.\n\n" +
		"**Commented** rows are optional: the code default applies until you set them.\n\n")
	for _, section := range sections {
		if len(section.vars) == 0 {
			continue
		}
		fmt.Fprintf(&b, "## %s\n\n| Variable | Example | Notes |\n| --- | --- | --- |\n", section.title)
		for _, v := range section.vars {
			value := "—"
			if v.value != "" {
				value = "`" + cell(v.value) + "`"
			}
			name := "`" + v.name + "`"
			note := v.note
			if v.optional {
				note = strings.TrimSpace("*Optional.* " + note)
			}
			fmt.Fprintf(&b, "| %s | %s | %s |\n", name, value, cell(note))
		}
		b.WriteString("\n")
	}
	return b.String()
}

// splitComment separates `value   # note` (a # preceded by whitespace).
func splitComment(raw string) (string, string) {
	for i := 0; i < len(raw); i++ {
		if raw[i] == '#' && (i == 0 || raw[i-1] == ' ' || raw[i-1] == '\t') {
			return strings.TrimSpace(raw[:i]), strings.TrimSpace(raw[i+1:])
		}
	}
	return strings.TrimSpace(raw), ""
}

// ── Permissions ──────────────────────────────────────────────────────────

// Permissions renders the permission catalog grouped by resource, with the
// seeded roles that hold each permission.
func Permissions() string {
	admin := names(authz.AdminTenantPermissions())
	developer := names(authz.DeveloperPermissions())

	groups := map[string][]authz.Permission{}
	var order []string
	for _, permission := range authz.Catalog {
		if _, seen := groups[permission.Group]; !seen {
			order = append(order, permission.Group)
		}
		groups[permission.Group] = append(groups[permission.Group], permission)
	}

	var b strings.Builder
	b.WriteString(header("Permissions reference", "Every permission in the catalog, generated from internal/authz/catalog.go.",
		"internal/authz/catalog.go"))
	fmt.Fprintf(&b, "%d permissions in %d groups. Super-Admin bypasses every check. A tenant **Admin** holds the\n"+
		"tenant-level permissions; the **Developer** role holds the dashboard ones. Add a permission to\n"+
		"`internal/authz/catalog.go`, then run `ims permission:sync`.\n\n", len(authz.Catalog), len(order))
	for _, group := range order {
		fmt.Fprintf(&b, "## %s\n\n| Permission | Description | Seeded roles |\n| --- | --- | --- |\n", group)
		for _, permission := range groups[group] {
			var roles []string
			if admin[permission.Name] {
				roles = append(roles, "Admin")
			}
			if developer[permission.Name] {
				roles = append(roles, "Developer")
			}
			if permission.IsSystem {
				roles = append(roles, "system")
			}
			held := "Super-Admin only"
			if len(roles) > 0 {
				held = strings.Join(roles, ", ")
			}
			fmt.Fprintf(&b, "| `%s` | %s | %s |\n", permission.Name, cell(permission.Description), held)
		}
		b.WriteString("\n")
	}
	return b.String()
}

func names(permissions []authz.Permission) map[string]bool {
	out := make(map[string]bool, len(permissions))
	for _, permission := range permissions {
		out[permission.Name] = true
	}
	return out
}

// ── Make ─────────────────────────────────────────────────────────────────

var makeTarget = regexp.MustCompile(`^([a-zA-Z0-9][a-zA-Z0-9_-]*):[^=#]*##\s*(.+)$`)

// Make renders every documented Makefile target (`target: ## description`).
func Make(makefile []byte) string {
	var b strings.Builder
	b.WriteString(header("Make targets", "Every make target, generated from the Makefile.", "the Makefile"))
	b.WriteString("Shortcuts for the commands you run every day. They only need `go` (and `npm` for the dashboard\n" +
		"and docs site), so they work the same on Windows, macOS and Linux. `make help` prints this list.\n\n" +
		"| Target | What it does |\n| --- | --- |\n")
	scanner := bufio.NewScanner(bytes.NewReader(makefile))
	for scanner.Scan() {
		if m := makeTarget.FindStringSubmatch(scanner.Text()); m != nil {
			fmt.Fprintf(&b, "| `make %s` | %s |\n", m[1], cell(m[2]))
		}
	}
	return b.String()
}
